199			name    string
200			date    string
201			reason  string
202			num     string
203			wantVal bool
204		}{
205			{"空白原因", "2026-11-05", "  ", "P-1", true},
206			{"早于操作当天", "2026-10-01", "提前", "P-1", true},
207			{"不存在的日期", "2026-11-31", "x", "P-1", true},
208			{"未知计划", "2026-11-05", "x", "NOPE", false},
209		}
210		for _, tc := range bad {
211			t.Run(tc.name, func(t *testing.T) {
212				p, err := l.ReschedulePlan(tc.num, tc.date, tc.reason)
213				if err == nil {
