8		"testing"
9	)
10	
11	// TestFailedCancelSaveLeavesNoChange 覆盖核心修复：已通过业务校验的取消在
12	// 写盘失败时明确报保存错误，计划仍为取消前的未完成状态——当前计划日期、最初
13	// 计划日期、说明与改期历史保持原样，取消时间和原因不留下本次申请的内容；
14	// 待办仍列出该计划，按器具核对也展示尚未取消的计划。恢复可写后重新提交才生效，
15	// 取消时间和原因取本次成功提交而非失败那次。
16	func TestFailedCancelSaveLeavesNoChange(t *testing.T) {
17		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
18		path := filepath.Join(t.TempDir(), "ledger.json")
19		l, err := openAt(path, clock.now)
20		if err != nil {
21			t.Fatalf("open: %v", err)
22		}
23		mustRegister(t, l, "M-1", "万用表", 0.5)
24		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1",
25			Date: "2026-10-10", Note: "周期校准"})
26	
27		// 一条成功的改期留痕：10-10 → 10-20，失败取消不得改动它。
28		clock.t = mustDate(t, "2026-10-03")
29		if _, err := l.ReschedulePlan("P-1", "2026-10-20", "实验室排期冲突"); err != nil {
30			t.Fatalf("改期应成功: %v", err)
31		}
32		savedChange := l.findPlan("P-1").Changes[0]
33	
34		// 提交合法取消时台账文件无法替换。
35		clock.t = mustDate(t, "2026-10-04")
36		blockSaving(t, l)
37		p, err := l.CancelPlan("P-1", "暂停送检")
38		if err == nil {
39			t.Fatal("台账文件无法替换时必须返回保存错误")
40		}
41		if p != nil {
42			t.Fatalf("保存失败不能返回成功的计划结果：%+v", p)
43		}
44		if IsValidation(err) || errors.Is(err, ErrNotFound) {
45			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
46		}
47	
48		// 文件仍不可写时再次提交：仍报保存错误，不能因为上一次失败就按“已结束”拒绝。
49		if p2, err := l.CancelPlan("P-1", "暂停送检"); err == nil || p2 != nil {
50			t.Fatalf("再次提交应仍报保存失败：err=%v plan=%v", err, p2)
51		} else if IsValidation(err) {
52			t.Fatalf("再次提交不得被当成已结束而业务拒绝：%v", err)
53		}
54	
55		// 继续使用同一台账对象，无需重新打开：计划仍为取消前的未完成状态，
56		// 编号、所属器具、当前与最初计划日期、说明、改期历史都保持原样，
57		// 取消时间和原因不能留下本次申请的内容。
58		cur := l.findPlan("P-1")
59		if cur == nil {
60			t.Fatal("计划丢失")
61		}
62		if !cur.Open() || cur.Status != PlanStatusOpen {
63			t.Fatalf("失败取消后计划不应结束：%+v", cur)
64		}
65		if cur.PlannedDate != "2026-10-20" || cur.OriginalDate != "2026-10-10" ||
66			cur.Note != "周期校准" || cur.Number != "P-1" || cur.InstrumentID != "M-1" {
67			t.Fatalf("失败取消改动了计划基本信息：%+v", cur)
68		}
69		if cur.CanceledAt != "" || cur.CancelReason != "" {
70			t.Fatalf("失败取消留下了取消时间或原因：%+v", cur)
71		}
72		if len(cur.Changes) != 1 || cur.Changes[0] != savedChange {
73			t.Fatalf("失败取消改动了改期历史：%+v", cur.Changes)
74		}
75	
76		// 待办仍能找到这项计划，并按查询当天判断标记：10-20 当天为“今天需校准”。
77		clock.t = mustDate(t, "2026-10-20")
78		items, err := l.Todos("")
79		if err != nil {
80			t.Fatalf("todos: %v", err)
81		}
82		if len(items) != 1 || items[0].PlanNumber != "P-1" ||
83			items[0].PlannedDate != "2026-10-20" || items[0].Marker != TodoToday {
84			t.Fatalf("待办应仍包含未取消的计划并标记今天需校准：%+v", items)
85		}
86		only, err := l.Todos("M-1")
87		if err != nil || len(only) != 1 || only[0].Marker != TodoToday {
88			t.Fatalf("按器具查待办异常：%+v err=%v", only, err)
89		}
