22		mustRegister(t, l, "M-1", "万用表", 0.5)
23		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1",
24			Date: "2026-10-10", Note: "周期校准"})
25		mustAddCert(t, l, CertificateInput{
26			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
27			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
28		})
29	
30		// 先成功改期一次 10-10 → 10-15：失败的完成不能改动计划日期与改期历史。
31		clock.t = mustDate(t, "2026-10-03")
32		first, err := l.ReschedulePlan("P-1", "2026-10-15", "实验室排期冲突")
33		if err != nil {
34			t.Fatalf("前置改期应成功: %v", err)
35		}
36		savedChange := first.Changes[0]
37	
38		// 合法完成在台账文件无法替换时写盘失败。
39		clock.t = mustDate(t, "2026-10-04")
40		blockSaving(t, l)
41		p, idem, err := l.CompletePlan("P-1", "C-1")
42		if err == nil {
43			t.Fatal("台账文件无法替换时必须返回保存错误")
44		}
45		if p != nil || idem {
46			t.Fatalf("保存失败不能返回成功的计划结果或标记重复完成：plan=%v idem=%v", p, idem)
47		}
48		if IsValidation(err) || errors.Is(err, ErrNotFound) {
49			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
50		}
51	
52		// 文件仍不可保存时再次提交同一计划同一证书：仍报保存失败，
53		// 而不是跳过保存返回“此前已完成”的成功结果。
54		if p2, idem2, err := l.CompletePlan("P-1", "C-1"); err == nil || p2 != nil || idem2 {
55			t.Fatalf("再次提交应仍报保存失败且不是重复完成：err=%v plan=%v idem=%v",
56				err, p2, idem2)
57		}
58	
59		// 继续使用同一台账对象：计划仍为未完成，完成时间与关联证书编号保持
60		// 操作前的值；计划日期、改期历史也不改变。
61		cur := l.findPlan("P-1")
62		if cur == nil {
63			t.Fatal("计划丢失")
64		}
65		if !cur.Open() || cur.CompletedAt != "" || cur.CertificateNumber != "" {
66			t.Fatalf("失败完成改动了完成信息：%+v", cur)
67		}
68		if cur.PlannedDate != "2026-10-15" || cur.OriginalDate != "2026-10-10" {
69			t.Fatalf("失败完成改动了计划日期：%+v", cur)
70		}
71		if len(cur.Changes) != 1 || cur.Changes[0] != savedChange {
72			t.Fatalf("失败完成改动了改期历史：%+v", cur.Changes)
73		}
74	
75		// 计划仍在待办中，日期标记按最后成功保存的计划日期与查询当天判断：
76		// 10-20 查询时 10-15 应为“逾期”；若误标完成，待办会直接为空。
77		clock.t = mustDate(t, "2026-10-20")
78		items, err := l.Todos("")
79		if err != nil {
80			t.Fatalf("todos: %v", err)
81		}
82		if len(items) != 1 || items[0].PlanNumber != "P-1" ||
83			items[0].PlannedDate != "2026-10-15" || items[0].Marker != TodoOverdue {
84			t.Fatalf("失败完成后计划应仍按 10-15 列入待办并标逾期：%+v", items)
85		}
86		only, err := l.Todos("M-1")
87		if err != nil || len(only) != 1 || only[0].Marker != TodoOverdue {
88			t.Fatalf("按器具核对待办异常：%+v err=%v", only, err)
89		}
90	
91		// 按器具核对与计划查询同样显示未完成、无关联证书与完成时间。
92		r, err := l.Review("M-1")
93		if err != nil {
94			t.Fatalf("review: %v", err)
95		}
96		if len(r.Plans) != 1 || r.Plans[0].Status != PlanStatusOpen ||
97			r.Plans[0].Marker != TodoOverdue ||
98			r.Plans[0].CompletedAt != "" || r.Plans[0].CertificateNumber != "" ||
99			len(r.Plans[0].Changes) != 1 {
100			t.Fatalf("核对结果应与失败前一致：%+v", r.Plans)
101		}
102		views, err := l.Plans("M-1")
103		if err != nil || len(views) != 1 || views[0].Status != PlanStatusOpen ||
104			views[0].CompletedAt != "" || views[0].CertificateNumber != "" {
105			t.Fatalf("计划查询应与失败前一致：%+v err=%v", views, err)
106		}
107	
108		// 恢复文件可写后不必重开台账：先做一次与完成无关、能够成功保存的正常
109		// 操作（停用器具），失败的完成信息不能被顺带写入文件。
110		restoreSaving(t, l)
111		if err := l.SetStatus("M-1", StatusRetired); err != nil {
112			t.Fatalf("恢复后正常操作应能保存: %v", err)
113		}
114		raw, err := os.ReadFile(path)
115		if err != nil {
116			t.Fatalf("读取台账文件: %v", err)
117		}
118		if strings.Contains(string(raw), "completed_at") ||
119			strings.Contains(string(raw), `"status": "已完成"`) ||
120			strings.Contains(string(raw), "2026-10-04T00:00:00Z") {
121			t.Fatalf("失败完成被随后成功的写盘顺带写入文件：\n%s", raw)
122		}
123		reopened, err := openAt(path, clock.now)
124		if err != nil {
125			t.Fatalf("reopen: %v", err)
126		}
127		rp := reopened.findPlan("P-1")
128		if rp == nil || !rp.Open() || rp.CompletedAt != "" || rp.CertificateNumber != "" {
129			t.Fatalf("文件中的计划应停留在完成前状态：%+v", rp)
130		}
131	
132		// 在同一台账对象重新提交同一计划同一证书：这是一次全新完成，而非幂等
133		// 返回；计划从待办移除，完成时间取本次成功操作（10-21）而非失败时刻。
134		clock.t = mustDate(t, "2026-10-21")
135		done, idem, err := l.CompletePlan("P-1", "C-1")
136		if err != nil || idem || done == nil {
137			t.Fatalf("恢复后重新提交应真正完成：err=%v idem=%v plan=%v", err, idem, done)
138		}
139		if done.Status != PlanStatusDone || done.CertificateNumber != "C-1" {
140			t.Fatalf("成功后完成信息异常：%+v", done)
141		}
142		if done.CompletedAt != "2026-10-21T00:00:00Z" {
143			t.Fatalf("完成时间应取本次成功操作而非失败时刻 10-04：%s", done.CompletedAt)
144		}
145		if items, err := l.Todos(""); err != nil || len(items) != 0 {
146			t.Fatalf("真正完成后应移出待办：%+v err=%v", items, err)
147		}
148		r, _ = l.Review("M-1")
149		if len(r.Plans) != 1 || r.Plans[0].Status != PlanStatusDone ||
150			r.Plans[0].CertificateNumber != "C-1" ||
151			r.Plans[0].CompletedAt != "2026-10-21T00:00:00Z" {
152			t.Fatalf("核对结果应显示本次成功完成的信息：%+v", r.Plans)
153		}
154		raw, err = os.ReadFile(path)
155		if err != nil {
156			t.Fatalf("读取台账文件: %v", err)
157		}
158		if !strings.Contains(string(raw), "2026-10-21T00:00:00Z") ||
159			strings.Contains(string(raw), "2026-10-04T00:00:00Z") {
160			t.Fatalf("文件应只含成功完成时间、不含失败时刻：\n%s", raw)
161		}
162		reopened, err = openAt(path, clock.now)
163		if err != nil {
164			t.Fatalf("reopen: %v", err)
165		}
166		rp = reopened.findPlan("P-1")
167		if rp == nil || rp.Status != PlanStatusDone || rp.CertificateNumber != "C-1" ||
168			rp.CompletedAt != "2026-10-21T00:00:00Z" {
169			t.Fatalf("重开后完成信息异常：%+v", rp)
170		}
171	
172		// 真正保存成功后，同证书重复完成同一计划才幂等返回原结果，时钟前进也
173		// 不刷新完成时间。
174		clock.t = mustDate(t, "2026-10-25")
175		again, idem2, err := l.CompletePlan("P-1", "C-1")
176		if err != nil || !idem2 {
177			t.Fatalf("成功后同证书重复完成应幂等：err=%v idem=%v", err, idem2)
178		}
179		if again.CompletedAt != done.CompletedAt {
180			t.Fatalf("重复完成刷新了完成时间：原 %s 现 %s", done.CompletedAt, again.CompletedAt)
181		}
182	}
183	
184	// TestCompleteValidationRejectedWhileSavingBlocked 区分文件读写错误与业务
185	// 拒绝：文件不可写时，不符合完成条件的请求仍按业务校验拒绝（不进行写盘
186	// 尝试、不改动任何记录），不能被保存错误替代。
187	func TestCompleteValidationRejectedWhileSavingBlocked(t *testing.T) {
188		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
189		path := filepath.Join(t.TempDir(), "ledger.json")
190		l, err := openAt(path, clock.now)
191		if err != nil {
192			t.Fatalf("open: %v", err)
193		}
194		mustRegister(t, l, "M-1", "万用表", 0.5)
195		mustRegister(t, l, "M-2", "示波器", 1.0)
196		mustRegister(t, l, "M-3", "信号源", 0.2)
197		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
198		mustAddCert(t, l, CertificateInput{
199			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
200			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
201		})
202		// 早于计划建立日期（10-02）的证书。
203		mustAddCert(t, l, CertificateInput{
204			InstrumentID: "M-1", Number: "C-OLD", CalDate: "2026-10-01",
205			Expiry: "2027-10-01", Method: "m", Error: 0.1, Summary: "s",
206		})
207		// 他器具证书。
208		mustAddCert(t, l, CertificateInput{
209			InstrumentID: "M-2", Number: "C-OTHER", CalDate: "2026-10-02",
210			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
211		})
212		// C-OTHER 已真正用于完成 M-2 的 P-2；M-2 另有未结束的 P-3。
213		mustPlan(t, l, PlanInput{Number: "P-2", InstrumentID: "M-2", Date: "2026-10-11", Note: "二"})
214		if _, _, err := l.CompletePlan("P-2", "C-OTHER"); err != nil {
215			t.Fatalf("C-OTHER 完成 P-2 应成功: %v", err)
216		}
217		mustPlan(t, l, PlanInput{Number: "P-3", InstrumentID: "M-2", Date: "2026-11-11", Note: "三"})
218		// 已取消的计划（建在尚无未结束计划的 M-3 上；完成已取消计划在检查
219		// 证书归属前即被拒绝）。
220		mustPlan(t, l, PlanInput{Number: "P-X", InstrumentID: "M-3", Date: "2026-12-12", Note: "x"})
221		if _, err := l.CancelPlan("P-X", "暂停送检"); err != nil {
222			t.Fatalf("cancel P-X: %v", err)
223		}
224	
225		blockSaving(t, l)
226		cases := []struct {
227			name   string
228			plan   string
229			cert   string
230			notVal bool
231		}{
232			{"他器具证书", "P-1", "C-OTHER", false},
233			{"证书早于计划建立日期", "P-1", "C-OLD", false},
234			{"证书已用于完成其他计划", "P-3", "C-OTHER", false},
235			{"完成已取消计划", "P-X", "C-1", false},
236			{"未知证书", "P-1", "C-NO", true},
237			{"未知计划", "P-NO", "C-1", true},
238		}
239		for _, tc := range cases {
240			t.Run(tc.name, func(t *testing.T) {
241				p, idem, err := l.CompletePlan(tc.plan, tc.cert)
242				if err == nil {
243					t.Fatalf("用例 %q 应被拒绝", tc.name)
244				}
245				if p != nil || idem {
246					t.Fatalf("业务拒绝不能返回计划结果或标记重复：%+v", p)
247				}
248				if tc.notVal {
249					if !errors.Is(err, ErrNotFound) {
250						t.Fatalf("用例 %q 应报 ErrNotFound：%v", tc.name, err)
251					}
252				} else if !IsValidation(err) {
253					t.Fatalf("用例 %q 应是业务校验错误而非文件错误：%v", tc.name, err)
254				}
255			})
256		}
257	
258		got := l.findPlan("P-1")
259		if !got.Open() || got.CompletedAt != "" || got.CertificateNumber != "" {
260			t.Fatalf("业务拒绝后 P-1 被改动：%+v", got)
261		}
262		// 业务拒绝没有触碰写盘：恢复后同一台账中 C-OTHER 仍只关联 P-2，
263		// P-3 保持未完成（业务拒绝不产生任何暂存改动）。
264		restoreSaving(t, l)
265		if rp := l.findPlan("P-3"); rp == nil || !rp.Open() || rp.CertificateNumber != "" {
266			t.Fatalf("P-3 应仍未完成：%+v", rp)
267		}
268		if px := l.findPlan("P-X"); px == nil || px.Status != PlanStatusCanceled {
269			t.Fatalf("P-X 应保持已取消：%+v", px)
270		}
271		// 恢复可写后 P-1 仍可用同一证书正常完成。
272		done, idem, err := l.CompletePlan("P-1", "C-1")
273		if err != nil || idem || done == nil || done.Status != PlanStatusDone {
274			t.Fatalf("恢复后 P-1 应能正常完成：err=%v idem=%v plan=%v", err, idem, done)
275		}
276	}
277	
278	// TestFailedCompleteWithOutOfToleranceCertGrantsNoQualification 验证超差证书
279	// 的失败完成同样不留任何结论；恢复后它能完成计划，但器具不会因此获得使用
280	// 资格（仍按最近证书超差判定）。
281	func TestFailedCompleteWithOutOfToleranceCertGrantsNoQualification(t *testing.T) {
282		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
283		path := filepath.Join(t.TempDir(), "ledger.json")
284		l, err := openAt(path, clock.now)
285		if err != nil {
286			t.Fatalf("open: %v", err)
287		}
288		mustRegister(t, l, "M-1", "万用表", 0.5)
289		if err := l.SetStatus("M-1", StatusInUse); err != nil {
290			t.Fatalf("set in-use: %v", err)
291		}
292		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
293		mustAddCert(t, l, CertificateInput{
294			InstrumentID: "M-1", Number: "C-BAD", CalDate: "2026-10-02",
295			Expiry: "2027-10-02", Method: "m", Error: 5, Summary: "超差",
296		})
297	
298		blockSaving(t, l)
299		if p, _, err := l.CompletePlan("P-1", "C-BAD"); err == nil || p != nil {
300			t.Fatalf("超差证书的失败完成也应报保存错误且不返回计划：err=%v plan=%v", err, p)
301		}
302		if got := l.findPlan("P-1"); !got.Open() || got.CertificateNumber != "" {
303			t.Fatalf("失败后计划应仍未完成：%+v", got)
304		}
305	
306		restoreSaving(t, l)
307		done, idem, err := l.CompletePlan("P-1", "C-BAD")
308		if err != nil || idem || done == nil || done.Status != PlanStatusDone {
309			t.Fatalf("恢复后超差证书应能真正完成计划：err=%v idem=%v plan=%v", err, idem, done)
310		}
311		// 计划完成不改变使用资格：在用 + 最近证书超差仍被拒绝。
312		d, err := l.RequestUse("M-1")
313		if err != nil {
314			t.Fatalf("request use: %v", err)
315		}
316		if d.Allowed || !containsReason(d.Reasons, "超差") {
317			t.Fatalf("超差证书完成计划不应授予使用资格：allowed=%v reasons=%v", d.Allowed, d.Reasons)
318		}
319	}
