154	// TestSeparatelyFetchedPlanResultsIndependent 验证操作结果、两次按器具查询、
155	// 两次核对各自独立：整理其中一份的字段或增删调换改期记录，其他份与台账内
156	// 正式计划都不变化。
157	func TestSeparatelyFetchedPlanResultsIndependent(t *testing.T) {
158		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
159		l := newTestLedger(t, clock)
160		mustRegister(t, l, "M-1", "万用表", 0.5)
161		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "周期"})
162		if _, err := l.ReschedulePlan("P-1", "2026-10-20", "真实原因"); err != nil {
163			t.Fatalf("reschedule: %v", err)
164		}
165	
166		op, _ := l.ReschedulePlan("P-1", "2026-10-25", "第二次改期")
167		q1, _ := l.Plans("M-1")
168		q2, _ := l.Plans("M-1")
169		r1, _ := l.Review("M-1")
170		r2, _ := l.Review("M-1")
171	
172		// 整理操作结果：删改改期记录。
173		op.Changes[0].Reason = "操作结果改写"
174		op.Changes = op.Changes[:1]
175		op.PlannedDate = "2030-01-01"
176		for _, views := range [][]PlanView{q1, q2, r1.Plans, r2.Plans} {
177			v := findView(t, views, "P-1")
178			if v.PlannedDate != "2026-10-25" || len(v.Changes) != 2 ||
179				v.Changes[0].Reason != "真实原因" {
180				t.Fatalf("整理操作结果影响了其他已取得结果：%+v", v)
181			}
182		}
183	
184		// 整理第一份查询：调换并清空改期记录。
185		v1 := findView(t, q1, "P-1")
186		v1.Changes[0], v1.Changes[1] = v1.Changes[1], v1.Changes[0]
187		v1.Changes = nil
188		v1.Number = "P-伪造"
189		for _, views := range [][]PlanView{q2, r1.Plans, r2.Plans} {
190			v := findView(t, views, "P-1")
191			if len(v.Changes) != 2 || v.Changes[0].Reason != "真实原因" ||
192				v.Changes[1].Reason != "第二次改期" {
193				t.Fatalf("整理第一份查询影响了其他结果：%+v", v.Changes)
194			}
195		}
196		if got := l.findPlan("P-1"); got == nil || got.PlannedDate != "2026-10-25" {
197			t.Fatalf("整理查询结果回写了台账：%+v", got)
198		}
199	
200		// 整理第一份核对：追加展示用计划与改期记录，不影响第二份核对与查询。
201		r1.Plans[0].Changes = append(r1.Plans[0].Changes, PlanChange{Reason: "核对追加"})
202		r1.Plans = append(r1.Plans, PlanView{Plan: Plan{Number: "P-展示"}})
203		if len(r2.Plans) != 1 || len(r2.Plans[0].Changes) != 2 {
204			t.Fatalf("整理第一份核对影响了第二份核对：%+v", r2.Plans)
205		}
206		if len(q2) != 1 || len(q2[0].Changes) != 2 {
207			t.Fatal("整理核对结果影响了已取得的查询结果")
208		}
209		if n := len(l.data.Plans); n != 1 {
210			t.Fatalf("整理核对结果改变了台账内计划数量：%d", n)
211		}
212	}
213	
214	// TestReturnedCompletedPlanCannotReopenOrFreeCertificate 验证已完成计划的
215	// 返回结果被改成未完成或换掉证书编号后，正式计划仍保持完成，原证书仍算
216	// 已用于该计划；同一证书再次完成返回的原结果同样受保护。
217	func TestReturnedCompletedPlanCannotReopenOrFreeCertificate(t *testing.T) {
218		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
219		path := filepath.Join(t.TempDir(), "ledger.json")
220		l, err := openAt(path, clock.now)
221		if err != nil {
222			t.Fatalf("open: %v", err)
223		}
224		mustRegister(t, l, "M-1", "万用表", 0.5)
225		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
226		mustAddCert(t, l, CertificateInput{
227			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
228			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
229		})
230		done, idem, err := l.CompletePlan("P-1", "C-1")
231		if err != nil || idem {
232			t.Fatalf("首次完成应成功且非幂等，err=%v idem=%v", err, idem)
233		}
234		savedCompletedAt := done.CompletedAt
235	
236		// 调用方把完成结果改成未完成、换掉证书编号、清空完成时间。
237		done.Status = PlanStatusOpen
238		done.CertificateNumber = "C-伪造"
239		done.CompletedAt = ""
240	
241		// 正式计划仍完成、原证书仍占用：同器具的新计划不能再用 C-1 完成。
242		mustPlan(t, l, PlanInput{Number: "P-2", InstrumentID: "M-1", Date: "2026-11-10", Note: "二"})
243		if _, _, err := l.CompletePlan("P-2", "C-1"); !IsValidation(err) {
244			t.Fatalf("被“释放”的 C-1 仍应算已用于 P-1，得到 %v", err)
245		}
246		// 已完成计划仍不能改期或取消。
247		if _, err := l.ReschedulePlan("P-1", "2026-11-01", "x"); !IsValidation(err) {
248			t.Fatalf("被改成未完成的返回结果不应重新开放改期，得到 %v", err)
249		}
250		if _, err := l.CancelPlan("P-1", "x"); !IsValidation(err) {
251			t.Fatalf("已完成计划不应能取消，得到 %v", err)
252		}
253		off := l.findPlan("P-1")
254		if off.Status != PlanStatusDone || off.CertificateNumber != "C-1" ||
255			off.CompletedAt != savedCompletedAt {
256			t.Fatalf("正式完成计划被返回结果改写：%+v", off)
257		}
258		// 待办不含已完成计划。
259		if items, _ := l.Todos(""); len(items) != 1 || items[0].PlanNumber != "P-2" {
260			t.Fatalf("待办不应包含被改成未完成的已完成计划：%+v", items)
261		}
262	
263		// 时钟前进后再次用同一证书完成：仍按正式记录幂等返回原结果、原完成时间，
264		// 且这份原结果也是独立副本。
265		clock.t = mustDate(t, "2026-10-05")
266		again, idem2, err := l.CompletePlan("P-1", "C-1")
267		if err != nil || !idem2 {
268			t.Fatalf("重复完成应幂等成功，err=%v idem=%v", err, idem2)
269		}
270		if again.Status != PlanStatusDone || again.CertificateNumber != "C-1" ||
271			again.CompletedAt != savedCompletedAt {
272			t.Fatalf("幂等返回应是正式原结果：%+v", again)
273		}
274		again.Status = PlanStatusOpen
275		again.CertificateNumber = "C-伪造2"
276		if off := l.findPlan("P-1"); off.Status != PlanStatusDone || off.CertificateNumber != "C-1" {
277			t.Fatalf("整理幂等返回结果改写了正式计划：%+v", off)
278		}
279		third, idem3, _ := l.CompletePlan("P-1", "C-1")
280		if !idem3 || third.Status != PlanStatusDone || third.CertificateNumber != "C-1" ||
281			third.CompletedAt != savedCompletedAt {
282			t.Fatalf("再次幂等返回应仍为正式原结果：%+v idem=%v", third, idem3)
283		}
284	
285		// 写盘重开后仍是完成、原证书归属不变。
286		_ = l.SetStatus("M-1", StatusRetired)
287		reopened, err := openAt(path, clock.now)
288		if err != nil {
289			t.Fatalf("reopen: %v", err)
290		}
291		rop := reopened.findPlan("P-1")
292		if rop.Status != PlanStatusDone || rop.CertificateNumber != "C-1" ||
293			rop.CompletedAt != savedCompletedAt {
294			t.Fatalf("写盘后完成计划被污染：%+v", rop)
295		}
296	}
297	
298	// TestReturnedCanceledPlanStaysCanceled 验证取消结果被改回未完成、清空取消
299	// 信息后，正式计划仍保持已取消：不列入待办，不能改期或再次取消，编号不释放。
300	func TestReturnedCanceledPlanStaysCanceled(t *testing.T) {
301		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
302		l := newTestLedger(t, clock)
303		mustRegister(t, l, "M-1", "万用表", 0.5)
304		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
305	
306		canceled, err := l.CancelPlan("P-1", "停产")
307		if err != nil {
308			t.Fatalf("cancel: %v", err)
309		}
310		canceled.Status = PlanStatusOpen
311		canceled.CanceledAt = ""
312		canceled.CancelReason = ""
313	
314		if items, _ := l.Todos(""); len(items) != 0 {
315			t.Fatalf("被改回未完成的取消结果不应重新进入待办：%+v", items)
316		}
317		if _, err := l.ReschedulePlan("P-1", "2026-10-20", "x"); !IsValidation(err) {
318			t.Fatalf("已取消计划不应能改期，得到 %v", err)
319		}
320		if _, err := l.CancelPlan("P-1", "x"); !IsValidation(err) {
321			t.Fatalf("已取消计划不应能再次取消，得到 %v", err)
322		}
323		if _, err := l.CreatePlan(PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-20", Note: "复用"}); !IsValidation(err) {
324			t.Fatalf("取消计划编号不应被释放，得到 %v", err)
325		}
326		off := l.findPlan("P-1")
327		if off.Status != PlanStatusCanceled || off.CancelReason != "停产" || off.CanceledAt == "" {
328			t.Fatalf("正式取消计划被返回结果改写：%+v", off)
329		}
330	}
331	
332	// TestReturnedCreatedPlanMutationHasNoOfficialEffect 验证建立计划返回结果的
333	// 整理不占用或释放正式编号、不改变未结束计划数量判断，也不被后续写盘带入文件。
334	func TestReturnedCreatedPlanMutationHasNoOfficialEffect(t *testing.T) {
335		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
336		path := filepath.Join(t.TempDir(), "ledger.json")
337		l, err := openAt(path, clock.now)
338		if err != nil {
339			t.Fatalf("open: %v", err)
340		}
341		mustRegister(t, l, "M-1", "万用表", 0.5)
342		mustRegister(t, l, "M-2", "示波器", 1.0)
343	
344		created := mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
345		created.Number = "P-FAKE"
346		created.Status = PlanStatusDone
347		created.PlannedDate = "2026-12-31"
348		created.Changes = []PlanChange{{From: "x", To: "y", Reason: "展示用"}}
349	
350		// 正式编号仍占用、伪造编号未占用；M-1 仍有一项未结束计划。
351		if _, err := l.CreatePlan(PlanInput{Number: "P-1", InstrumentID: "M-2", Date: "2026-10-11", Note: "x"}); !IsValidation(err) {
352			t.Fatalf("P-1 仍应被正式占用，得到 %v", err)
353		}
354		if l.findPlan("P-FAKE") != nil {
355			t.Fatal("只改返回结果的编号不应在台账中占用伪造编号")
356		}
357		if _, err := l.CreatePlan(PlanInput{Number: "P-2", InstrumentID: "M-1", Date: "2026-10-11", Note: "x"}); !IsValidation(err) {
358			t.Fatalf("M-1 的正式计划仍未结束，第二项应拒绝，得到 %v", err)
359		}
360		if items, _ := l.Todos(""); len(items) != 1 || items[0].PlanNumber != "P-1" {
361			t.Fatalf("被改成已完成的返回结果不应影响待办，得到 %+v", items)
362		}
363	
364		_ = l.SetStatus("M-1", StatusRetired)
365		reopened, err := openAt(path, clock.now)
366		if err != nil {
367			t.Fatalf("reopen: %v", err)
368		}
369		off := reopened.findPlan("P-1")
370		if off == nil || off.Status != PlanStatusOpen || off.PlannedDate != "2026-10-10" ||
371			len(off.Changes) != 0 {
372			t.Fatalf("写盘后展示内容被带入台账：%+v", off)
373		}
374		if reopened.findPlan("P-FAKE") != nil {
375			t.Fatal("展示用伪造编号不应进入台账")
376		}
377	}
378	
379	// TestPlanEmptyResultsStayEmpty 验证没有计划或没有改期历史时维持既有空结果
380	// 表现，且对空返回的整理不影响台账。
381	func TestPlanEmptyResultsStayEmpty(t *testing.T) {
382		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
383		l := newTestLedger(t, clock)
384		mustRegister(t, l, "M-1", "万用表", 0.5)
385		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "一"})
386	
387		// 没有改期历史：各入口的 Changes 保持空，追加展示记录不回写。
388		views, err := l.Plans("M-1")
389		if err != nil || len(views) != 1 || len(views[0].Changes) != 0 {
390			t.Fatalf("无改期历史时应保持空：%+v err=%v", views, err)
391		}
392		views[0].Changes = append(views[0].Changes, PlanChange{Reason: "展示用"})
393		r, _ := l.Review("M-1")
394		if len(r.Plans[0].Changes) != 0 {
395			t.Fatal("向空查询追加展示记录改写了核对结果")
396		}
397		if len(l.findPlan("P-1").Changes) != 0 {
398			t.Fatal("向空查询追加展示记录改写了台账")
399		}
400	
401		// 没有计划的器具：查询与核对中的计划列表保持空。
402		mustRegister(t, l, "M-2", "示波器", 1.0)
403		if empty, err := l.Plans("M-2"); err != nil || len(empty) != 0 {
404			t.Fatalf("无计划器具应返回空计划列表：%+v err=%v", empty, err)
405		}
406		r2, _ := l.Review("M-2")
407		if len(r2.Plans) != 0 {
408			t.Fatalf("无计划器具核对中不应出现计划：%+v", r2.Plans)
409		}
410		if items, err := l.Todos("M-2"); err != nil || len(items) != 0 {
411			t.Fatalf("无计划器具应无待办：%+v err=%v", items, err)
412		}
413	}
