495		if old == nil || old.Status != PlanStatusDone || old.CertificateNumber != "C-1" {
496			t.Fatalf("已结束计划及关联证书展示异常：%+v", old)
497		}
498		if cur == nil || cur.PlannedDate != "2026-11-05" || cur.OriginalDate != "2026-11-01" {
499			t.Fatalf("当前计划日期展示异常：%+v", cur)
500		}
501		if len(cur.Changes) != 1 || cur.Changes[0].Reason != "车间占用" {
502			t.Fatalf("改期记录未展示：%+v", cur)
503		}
504		if cur.Marker != TodoFuture {
505			t.Fatalf("未来计划标记应为未到计划日，得到 %s", cur.Marker)
506		}
507	}
508	
509	func TestPlansPersistAndOldLedgerHasNoPlans(t *testing.T) {
510		dir := t.TempDir()
511		path := filepath.Join(dir, "ledger.json")
512		clock := func() time.Time { return mustDate(t, "2026-10-02") }
513	
514		l, err := openAt(path, clock)
515		if err != nil {
516			t.Fatalf("open: %v", err)
517		}
518		mustRegister(t, l, "M-1", "万用表", 0.5)
519		mustPlan(t, l, PlanInput{Number: "P-1", InstrumentID: "M-1", Date: "2026-10-10", Note: "周期"})
520		if _, err := l.ReschedulePlan("P-1", "2026-10-20", "改期留痕"); err != nil {
521			t.Fatalf("reschedule: %v", err)
522		}
523	
524		// 关闭后重开：计划与改期历史保留。
525		reopened, err := openAt(path, clock)
526		if err != nil {
527			t.Fatalf("reopen: %v", err)
528		}
529		p := reopened.findPlan("P-1")
530		if p == nil || p.PlannedDate != "2026-10-20" || p.OriginalDate != "2026-10-10" {
531			t.Fatalf("重开后计划丢失：%+v", p)
532		}
533		if len(p.Changes) != 1 || p.Changes[0].Reason != "改期留痕" {
534			t.Fatalf("重开后改期历史丢失：%+v", p)
535		}
536		// 原有证书、使用记录入口仍可用。
537		mustAddCert(t, reopened, CertificateInput{
538			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
539			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
540		})
541		if _, _, err := reopened.CompletePlan("P-1", "C-1"); err != nil {
542			t.Fatalf("重开后应能继续完成计划：%v", err)
543		}
544	
545		// 旧台账文件（没有 plans 字段）按无计划处理，且可以正常新增计划。
546		oldPath := filepath.Join(dir, "old.json")
547		oldRaw, _ := json.Marshal(map[string]any{
548			"version": 1,
549			"instruments": []Instrument{{
550				ID: "OLD-1", Name: "老表", AllowedError: 0.5,
551				Status: StatusPending, RegisteredAt: "2026-09-01T00:00:00Z",
552			}},
553			"certificates": []Certificate{},
554			"usage":        []UsageRecord{},
555		})
556		if err := os.WriteFile(oldPath, oldRaw, 0o644); err != nil {
557			t.Fatalf("write old ledger: %v", err)
558		}
559		oldLedger, err := openAt(oldPath, clock)
560		if err != nil {
561			t.Fatalf("open old: %v", err)
562		}
563		items, err := oldLedger.Todos("")
564		if err != nil || len(items) != 0 {
565			t.Fatalf("旧台账应按无计划处理，items=%+v err=%v", items, err)
566		}
567		plans, err := oldLedger.Plans("OLD-1")
568		if err != nil || len(plans) != 0 {
569			t.Fatalf("旧台账器具应无计划，plans=%+v err=%v", plans, err)
570		}
571		if _, err := oldLedger.CreatePlan(PlanInput{
572			Number: "P-OLD-1", InstrumentID: "OLD-1", Date: "2026-10-10", Note: "补建",
573		}); err != nil {
574			t.Fatalf("旧台账应能新增计划：%v", err)
